/**
 * Advanced Bug Bounty Lab — tool registry, payloads, and workflow for /offensive/lab?tab=bounty
 * Authorized targets only. Active probes run in user-controlled shells (Kali/Fly), not edge functions.
 */

export type BountyToolCategory =
  | "recon"
  | "discovery"
  | "scanning"
  | "injection"
  | "oast"
  | "practice"
  | "workflow";

export type BountyToolKind = "link" | "shell" | "in-app" | "embedded" | "platform";

export type BountyTool = {
  id: string;
  name: string;
  description: string;
  category: BountyToolCategory;
  kind: BountyToolKind;
  url?: string;
  /** Run in Kali/Fly/cloud shell after install */
  shellCommand?: string;
  installHint?: string;
  tags: string[];
  cost: "free" | "freemium";
};

export type BountyPayload = {
  id: string;
  category: "xss" | "sqli" | "ssrf" | "lfi" | "redirect" | "xxe" | "idor" | "ssti";
  label: string;
  payload: string;
  note?: string;
};

