export function toolsByCategory(category: BountyToolCategory): BountyTool[] {
  return BUG_BOUNTY_TOOLS.filter((t) => t.category === category);
}

export function payloadsByCategory(category: BountyPayload["category"]): BountyPayload[] {
  return BUG_BOUNTY_PAYLOADS.filter((p) => p.category === category);
}

export function shellCommandForTarget(cmd: string, target: string): string {
  return cmd.replace(/TARGET/g, target);
}

export function bountyLabUrl(target?: string, vuln?: string): string {
  const params = new URLSearchParams({ tab: "bounty" });
  if (target) params.set("target", target);
  if (vuln) params.set("vuln", vuln);
  return `/offensive/lab?${params.toString()}`;
}

export type BountyScope = {
  program: string;
  inScope: string[];
  outOfScope: string[];
  notes: string;
  updatedAt: string;
};

const SCOPE_KEY = "threatlens_bounty_scope";

export function loadBountyScope(): BountyScope | null {
  try {
    const raw = localStorage.getItem(SCOPE_KEY);
    return raw ? (JSON.parse(raw) as BountyScope) : null;
  } catch {
    return null;
  }
}

export function saveBountyScope(scope: BountyScope): void {
  localStorage.setItem(SCOPE_KEY, JSON.stringify({ ...scope, updatedAt: new Date().toISOString() }));
}
