export async function sha256Hex(input: string): Promise<string> {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(input));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export async function sha1Hex(input: string): Promise<string> {
  const buf = await crypto.subtle.digest("SHA-1", new TextEncoder().encode(input));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export function decodeJwtPayload(token: string): { header: unknown; payload: unknown; error?: string } {
  try {
    const parts = token.trim().split(".");
    if (parts.length < 2) return { header: null, payload: null, error: "Not a JWT (need header.payload)" };
    const decode = (s: string) => JSON.parse(atob(s.replace(/-/g, "+").replace(/_/g, "/")));
    return { header: decode(parts[0]), payload: decode(parts[1]) };
  } catch (e) {
    return { header: null, payload: null, error: e instanceof Error ? e.message : "Decode failed" };
  }
}

export function base64Encode(text: string): string {
  return btoa(unescape(encodeURIComponent(text)));
}

export function base64Decode(text: string): { ok: true; value: string } | { ok: false; error: string } {
  try {
    return { ok: true, value: decodeURIComponent(escape(atob(text.trim()))) };
  } catch {
    return { ok: false, error: "Invalid base64" };
  }
}
